import{_ as o,o as s,c as a,a as e}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"写作课作业-013","description":"","frontmatter":{"date":"2020-08-11T20:06:43","title":"写作课作业-013","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/013.md","filePath":"posts/homework/013.md"}'),r={name:"posts/homework/013.md"};function n(l,t,p,c,d,i){return s(),a("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"写一次吃货经历。调动各个感官，传达这个菜或东西很好吃的感知。勾起读者想要去吃的欲望。")],-1),e("p",null,"今天看到作业，想来自己不是吃货，除了好吃不懂还有什么，想着想着，小学班主任说的一次经历浮现出来，他说刚工作的时候，从一个镇到另一个镇的学校去上班，是骑自行车去，到学校时已经过了吃饭的点，饥肠辘辘的问食堂还有什么，只剩一些白米饭，于是他白米饭就着白开水吃了他的第一顿饭，他说后面再也没吃过那么香那么甜的米饭，说话时像是吧唧着嘴，眼里透着光，满是回忆。",-1),e("p",null,"其实自己每次回老家的时候，也是要来碗勾汤的，有些人爱说兜汤，我觉得勾汤更有味。刚到店门口就用土话朝老板喊说来碗牛肉勾汤，自己选个位置坐下，这种汤店一般门面不大，能摆个三四桌的样子，基本就是拼桌的。一会老板就端着满满一碗牛肉和一杯汤上来了，满满一碗牛肉不是说没汤，只是汤比较少。大小不规则的牛肉块被透亮的带着酱色的淀粉裹着，滑滑的，能看到牛肉的纹路。咬上一口，顺滑柔嫩，有些肉会有些筋于是就Q弹起来，吃上了几口肉，和上几口汤，算是原味，然后加些辣椒和醋，搅拌时也不会洒出来，我只爱吃醋，一会囫囵下肚了，不过瘾，拿起杯子往碗里倒汤，那汤粘而不稠，勾汤的汤是老汤，店家每天要留下小半桶明天用，看着混，打到汤勺里清着呢，吃上一口就是那味了，小时候总是不停地喊老板加汤，还盼着汤里多块肉。",-1)])])}const _=o(r,[["render",n]]);export{u as __pageData,_ as default};
